--
-- TOC entry 245 (class 1255 OID 16399)
-- Name: ingest_practice_suggestions(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_practice_suggestions(bundle jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  inserted_count INT := 0;
BEGIN
  WITH items AS (
    SELECT jsonb_array_elements(COALESCE(bundle->'items', '[]'::jsonb)) AS item
  ),
  candidates AS (
    SELECT
      ('practice::' || (item->>'id')) AS exercise_id,
      COALESCE(NULLIF(item #>> '{practice_suggestion,name}', ''), item->>'title', item->>'id') AS name,
      (item #> '{practice_suggestion,steps}') AS instructions
    FROM items
    WHERE
      item->>'type' = 'learning_module'
      AND (item #> '{practice_suggestion,steps}') IS NOT NULL
      AND jsonb_typeof(item #> '{practice_suggestion,steps}') = 'array'
      AND jsonb_array_length(item #> '{practice_suggestion,steps}') > 0
      AND item ? 'id'
  ),
  upserted AS (
    SELECT exercise_id, name, instructions
    FROM candidates
    ON CONFLICT (exercise_id) DO UPDATE SET
      name = EXCLUDED.name,
      instructions = EXCLUDED.instructions
    RETURNING 1
  )
  SELECT COUNT(*) INTO inserted_count FROM upserted;

  RETURN inserted_count;
END;
$$;


--
-- TOC entry 249 (class 1255 OID 16400)
-- Name: ingest_task_bundle(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ingest_task_bundle(bundle jsonb) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  inserted_count INT := 0;
BEGIN
  WITH items AS (
    SELECT jsonb_array_elements(COALESCE(bundle->'items', '[]'::jsonb)) AS item
  ),
  libs AS (
    SELECT item FROM items WHERE item->>'type' = 'task_library'
  ),
  tasks AS (
    SELECT t AS task
    FROM libs,
    LATERAL jsonb_array_elements(COALESCE(libs.item->'tasks', '[]'::jsonb)) AS t
  ),
  cleaned AS (
    SELECT
      task->>'task_id' AS exercise_id,
      COALESCE(NULLIF(task->>'name',''), task->>'task_id') AS name,
      task->'instructions' AS instructions
    FROM tasks
    WHERE
      task ? 'task_id'
      AND jsonb_typeof(task->'instructions') = 'array'
      AND jsonb_array_length(task->'instructions') > 0
  ),
  upserted AS (
    SELECT exercise_id, name, instructions FROM cleaned
    ON CONFLICT (exercise_id) DO UPDATE SET
      name = EXCLUDED.name,
      instructions = EXCLUDED.instructions
    RETURNING 1
  )
  SELECT COUNT(*) INTO inserted_count FROM upserted;

  RETURN inserted_count;
END;
$$;


--
-- TOC entry 255 (class 1255 OID 16401)
-- Name: next_exercise_step(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_exercise_step(p_user_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  ex_id TEXT;
  idx INT;
  steps JSONB;
  total_steps INT;
  new_idx INT;
BEGIN
  SELECT active_exercise_id, step_index INTO ex_id, idx
  FROM exercise_session
  WHERE user_id = p_user_id;

  IF ex_id IS NULL THEN
    RAISE EXCEPTION 'no_active_exercise';
  END IF;

  SELECT instructions INTO steps
  FROM exercise_content
  WHERE exercise_id = ex_id;

  IF steps IS NULL THEN
    RAISE EXCEPTION 'exercise_not_found';
  END IF;

  total_steps := jsonb_array_length(steps);
  new_idx := idx + 1;

  IF new_idx >= total_steps THEN
    UPDATE exercise_session
    SET active_exercise_id = NULL, step_index = 0, updated_at = now()
    WHERE user_id = p_user_id;

    RETURN jsonb_build_object(
      'exercise_id', ex_id,
      'step_index', total_steps,
      'total_steps', total_steps,
      'step_text', 'Finished.',
      'finished', true
    );
  END IF;

  UPDATE exercise_session
  SET step_index = new_idx, updated_at = now()
  WHERE user_id = p_user_id;

  RETURN jsonb_build_object(
    'exercise_id', ex_id,
    'step_index', new_idx,
    'total_steps', total_steps,
    'step_text', steps->>new_idx,
    'finished', false
  );
END;
$$;


--
-- TOC entry 254 (class 1255 OID 16402)
-- Name: start_exercise(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_exercise(p_user_id text, p_exercise_id text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  steps JSONB;
  total_steps INT;
BEGIN
  SELECT instructions INTO steps
  FROM exercise_content
  WHERE exercise_id = p_exercise_id;

  IF steps IS NULL THEN
    RAISE EXCEPTION 'exercise_not_found';
  END IF;

  IF jsonb_typeof(steps) <> 'array' OR jsonb_array_length(steps) = 0 THEN
    RAISE EXCEPTION 'exercise_has_no_steps';
  END IF;

  total_steps := jsonb_array_length(steps);

  VALUES (p_user_id, p_exercise_id, 0)
  ON CONFLICT (user_id) DO UPDATE SET
    active_exercise_id = EXCLUDED.active_exercise_id,
    step_index = 0,
    updated_at = now();

  RETURN jsonb_build_object(
    'exercise_id', p_exercise_id,
    'step_index', 0,
    'total_steps', total_steps,
    'step_text', steps->>0,
    'finished', false
  );
END;
$$;


--
-- TOC entry 243 (class 1255 OID 16403)
-- Name: suggest_exercises(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.suggest_exercises(p_text text, p_limit integer DEFAULT 3) RETURNS TABLE(exercise_id text, name text, score integer)
    LANGUAGE sql
    AS $$
  WITH q AS (SELECT lower(p_text) AS t),
  scored AS (
    SELECT
      e.exercise_id,
      e.name,
      (
        COALESCE((
          SELECT count(*) FROM unnest(e.cues_user) cu, q
          WHERE q.t LIKE '%' || lower(cu) || '%'
        ), 0)
        +
        COALESCE((
          SELECT count(*) FROM unnest(e.cues_body) cb, q
          WHERE q.t LIKE '%' || lower(cb) || '%'
        ), 0)
        +
        COALESCE((
          SELECT count(*) FROM unnest(e.tags) tg, q
          WHERE q.t LIKE '%' || lower(tg) || '%'
        ), 0)
      )::int AS score
    FROM public.exercise_content e
  )
  SELECT exercise_id, name, score
  FROM scored
  WHERE score > 0
  ORDER BY score DESC, name
  LIMIT p_limit;
$$;


